-- Usunięcie starych tabel, jeśli istnieją (dla czystej instalacji)DROP TABLE IF EXISTS commands;DROP TABLE IF EXISTS agents;DROP TABLE IF EXISTS users;DROP TABLE IF EXISTS custom_commands;DROP TABLE IF EXISTS agent_groups;DROP TABLE IF EXISTS agent_group_mapping;DROP TABLE IF EXISTS alert_rules;DROP TABLE IF EXISTS scheduled_tasks;DROP TABLE IF EXISTS audit_log;-- Tabela Użytkowników Panelu WebowegoCREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,-- Dostępne role: admin, onboarding_manager, command_sender, metric_viewer, viewerrole TEXT NOT NULL DEFAULT 'viewer',email TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,-- Nowe pola dla MFA (Feat. 11)
mfa_enabled INTEGER DEFAULT 0,
-- Sekret TOTP, ZASZYFROWANY przy użyciu klucza SECRET_KEY aplikacji
mfa_secret_encrypted TEXT, 
-- Zaszyfrowane kody zapasowe, oddzielone przecinkami
mfa_backup_codes_encrypted TEXT 
);-- Tabela Zarejestrowanych AgentówCREATE TABLE agents (id TEXT PRIMARY KEY,name TEXT NOT NULL,platform TEXT,api_key TEXT NOT NULL UNIQUE,created_by_user_id INTEGER NOT NULL,agent_version TEXT,agent_os_details TEXT,first_seen TEXT,last_seen TEXT DEFAULT CURRENT_TIMESTAMP,status TEXT DEFAULT 'offline',sid TEXT UNIQUE,alert_status INTEGER DEFAULT 0,FOREIGN KEY (created_by_user_id) REFERENCES users (id));-- Tabela Grup Agentów (Feat. 2)CREATE TABLE agent_groups (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,created_by_user_id INTEGER NOT NULL,FOREIGN KEY (created_by_user_id) REFERENCES users (id));-- Tabela Mapująca (Agenci <-> Grupy) (Feat. 2)CREATE TABLE agent_group_mapping (agent_id TEXT NOT NULL,group_id INTEGER NOT NULL,PRIMARY KEY (agent_id, group_id),FOREIGN KEY (agent_id) REFERENCES agents (id) ON DELETE CASCADE,FOREIGN KEY (group_id) REFERENCES agent_groups (id) ON DELETE CASCADE);-- Tabela Reguł Alertów (Feat. 5)CREATE TABLE alert_rules (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,metric TEXT NOT NULL, -- 'cpu', 'memory', 'disk'operator TEXT NOT NULL, -- '>', '<'threshold REAL NOT NULL,created_by_user_id INTEGER NOT NULL,FOREIGN KEY (created_by_user_id) REFERENCES users (id));-- Tabela Własnych Poleceń (Custom Commands)CREATE TABLE custom_commands (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,description TEXT,platform TEXT NOT NULL DEFAULT 'any',script_content TEXT NOT NULL,created_by_user_id INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (created_by_user_id) REFERENCES users (id));-- Tabela Zaplanowanych Zadań (Cron) (Feat. 9)CREATE TABLE scheduled_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT,target_type TEXT NOT NULL, -- 'agent' lub 'group'target_id TEXT NOT NULL,command_type TEXT NOT NULL,command_payload TEXT NOT NULL,cron_schedule TEXT NOT NULL,is_enabled INTEGER DEFAULT 1,created_by_user_id INTEGER NOT NULL,FOREIGN KEY (created_by_user_id) REFERENCES users (id));-- Tabela Historii PoleceńCREATE TABLE commands (id INTEGER PRIMARY KEY AUTOINCREMENT,agent_id TEXT NOT NULL,user_id INTEGER,command_type TEXT NOT NULL,command_payload TEXT NOT NULL,result TEXT,status TEXT DEFAULT 'sent',timestamp TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (agent_id) REFERENCES agents (id) ON DELETE CASCADE,FOREIGN KEY (user_id) REFERENCES users (id));-- Tabela Dziennika Audytu (Security Feat. 3)CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,username TEXT,ip_address TEXT,action TEXT NOT NULL, -- np. 'login_success', 'login_fail_password', 'login_fail_mfa', 'create_user', 'delete_agent'target_type TEXT, -- np. 'user', 'agent'target_id TEXT,details TEXT,timestamp TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users (id));
